insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'hoops-junkie', 'Hoops Junkie', array['tool']::listing_type[], 'Live NBA and WNBA scores, standings and advanced stats in a clean, fast app.', 'A basketball stats site and mobile app covering the NBA and WNBA. Live scores, standings, team and player pages, transactions and a set of advanced numbers such as pace, possessions and efficiency ratings, each with a plain explanation of how it is worked out. Free to use, with a paid Pro tier in the apps.', 'https://hoopsjunkie.io', 'freemium'::pricing_model, 'Free, with a paid Pro tier', array['nba']::text[], 'Stats and data', array['Free plan','Web app','iOS app','Android app']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Stats product, not betting. Low risk. Add the Pro price and what Pro unlocks. Country not stated.", "categories": ["Stats and data"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Hoops Junkie')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://hoopsjunkie.io'),('X','https://x.com/hoopsjunkie_io'),('Bluesky','https://bsky.app/profile/hoopsjunkie.io'),('App Store','https://apps.apple.com/app/id6764501238'),('Google Play','https://play.google.com/store/apps/details?id=io.hoopsjunkie.app')) as v(platform,url) where l.slug = 'hoops-junkie' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'statz', 'Statz', array['tool']::listing_type[], 'Football stats, AI match projections and bet builder tools for every major league.', 'A football stats platform with team and player data, power rankings and model projections for each fixture, including win chances and projected goals. Adds player prop projections, a bet builder, an acca builder, BTTS and corners trends and FPL stats, on the web and in iOS and Android apps. Also has NBA, NFL, cricket and golf sections.', 'https://statz.ai', 'freemium'::pricing_model, 'Free stats, with a paid Statz Pro tier; check current pricing', array['soccer']::text[], 'Stats and data', array['Web app','iOS app','Android app','Discord community','Telegram channel','Projections','Matchup data','Free picks']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "IMPORTANT: the site has a ''Best online bookmakers'' page and says it may earn commission from bookmaker links. Decide whether that fits your no-bookmaker stance before publishing. Run by CricLabs Ltd; the UK flag is a best guess from the company number, so confirm. Add Statz Pro pricing.", "country": "GB", "categories": ["Stats and data", "Models and projections", "Player prop research"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Statz')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://statz.ai'),('X','https://x.com/Statz_Ai'),('Instagram','https://www.instagram.com/statz.ai'),('Discord','https://discord.gg/HXqbhEJNsu'),('TikTok','https://www.tiktok.com/@statzai')) as v(platform,url) where l.slug = 'statz' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'cricdatapicks', 'CricDataPicks', array['tipster']::listing_type[], 'Daily cricket picks backed by venue and form stats.', 'A cricket analyst posting daily match predictions and player picks on X, each with the venue records and recent form behind it. Covers international T20s and the Big Bash, with a Telegram channel for followers.', 'https://x.com/AkshayCricPicks', 'free'::pricing_model, null, array['cricket']::text[], null, array['Free picks','Write-ups with reasoning','Telegram channel']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "DO NOT PUBLISH AS IS. Recent posts advertise betting ID services (CoVIPBook, Skyfair, SSexch), which are unlicensed bookmakers. Listing an account that promotes them cuts against your no-bookmaker rule and Australian law on advertising unlicensed gambling. Only consider it if he stops those posts. Small, new account (about 800 followers, joined December 2025)."}'::jsonb where not exists (select 1 from listings where lower(name) = lower('CricDataPicks')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/AkshayCricPicks')) as v(platform,url) where l.slug = 'cricdatapicks' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'sam-the-model-man', 'Sam The Model Man', array['tipster','creator']::listing_type[], 'Sports prediction models and projections, with picks posted on X.', 'Sam builds prediction models for US sports and posts projections and picks from them on X. The full set of models and data sits behind a paid membership on Whop.', 'https://x.com/TheModelManSam', 'freemium'::pricing_model, 'Free posts on X, with a paid membership for all models and data', array['nfl','nba']::text[], null, array['Projections','Free picks','Paid picks']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Check before publishing: the account shows 49K followers but a September 2026 join date, which is unusual. Posts are heavy on wins; ask for a tracked record. Confirm sports, pricing and the right membership link (Whop, Parlay Science). Country not stated."}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Sam The Model Man')) on conflict (slug) do nothing;
