insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'ben-on-racing', 'Ben on Racing', array['tipster']::listing_type[], 'Daily Australian horse racing tips with full cards and each-way value picks.', 'Ben posts daily tips for Australian race meetings on X and Telegram, with full cards, each-way picks at bigger prices and results posted afterwards.', 'https://x.com/BenOnRacing', 'free'::pricing_model, null, array['racing']::text[], null, array['Free picks','Telegram channel','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "New account (joined October 2026, about 1,100 followers). The winners count in his bio is his own claim; do not repeat it. He quotes fractional odds, so he may not be based in Australia; confirm country. Check the Telegram for any bookmaker promotion or paid upsell."}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Ben on Racing')) on conflict (slug) do nothing;
