insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'gambly', 'Gambly', array['tool']::listing_type[], 'A betting copilot: positive-EV bets, line shopping and one-click betslips.', 'Gambly pulls together positive-EV bets, odds comparison and ready-made betslips that open in your sportsbook. It adds game simulations, a bet builder, NBA hit rate trends and an AI chat assistant that can read a screenshot of a slip, with a Discord bot and iMessage option.', 'https://gambly.com', 'freemium'::pricing_model, 'Check current pricing', array['nfl','nba','ncaaf','soccer']::text[], 'Positive EV and arbitrage', array['Web app','Discord community','Positive EV finder','Odds comparison','Player prop hit rates']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "US product that deep-links into US sportsbooks and has a ''Bonus Finder'' for sportsbook promotions. Check what an Australian visitor is shown. Pricing is not on the homepage; confirm it and whether there is a free plan. US flag is a best guess (Gambly Inc.).", "country": "US", "categories": ["Positive EV and arbitrage", "Odds comparison"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Gambly')) on conflict (slug) do nothing;
