insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'krashboard', 'KrashBoard', array['tool']::listing_type[], 'Prop research, model projections and positive-EV bets for NFL, NBA, NHL and MLB.', 'A research dashboard from KrashWagers, built as a research platform and not a picks app. Tools include anytime touchdown probabilities with best prices, prop hit rates, player projections against sportsbook lines, a positive-EV list, a parlay generator, first basket and lineup impact pages, and calculators for hedging, Kelly staking and devigging.', 'https://www.krashboard.app', 'freemium'::pricing_model, 'Free pages to browse; USD $24.99 a month, cheaper on longer plans, with a $1 first week', array['nfl','nba','nhl','mlb']::text[], 'Player prop research', array['Free plan','Free trial','Web app','Player prop hit rates','Projections','Positive EV finder','Odds comparison','Betting calculators']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "The site links to the OnlyParlays picks Discord through a DubClub affiliate link and sells a bundle with it. Country not stated. Prices were read from the site on 27 November 2026; confirm before publishing.", "categories": ["Player prop research", "Models and projections", "Positive EV and arbitrage", "Betting calculators"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('KrashBoard')) on conflict (slug) do nothing;
