insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'courtai', 'CourtAI', array['tool']::listing_type[], 'NBA game log research you can search in plain English.', 'An NBA research tool built around player game logs. Search in plain English, apply detailed filters, and see matchup pages that flag which stats each player is likely to gain or lose against tonight''s opponent. Users can publish their own research reports for others to read.', 'https://www.courtai.app', 'freemium'::pricing_model, 'Free account; check whether a paid tier applies', array['nba']::text[], 'Player prop research', array['Free plan','Web app','Matchup data','Player prop hit rates']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Could not find pricing, social links or a company name on the homepage. Ask them for an X handle and pricing. Country not stated.", "categories": ["Player prop research", "Stats and data"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('CourtAI')) on conflict (slug) do nothing;
