insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'sharpr', 'Sharpr', array['tool']::listing_type[], 'Player prop projections and positive-EV bets for NBA and MLB.', 'Sharpr models each player prop as a full range of outcomes, then compares it with prices at more than 15 sportsbooks and exchanges to flag positive-EV bets. It tracks line movement, shows player research such as splits, trends and shot zones, and pushes lineup and injury alerts to Discord.', 'https://sharpr.bet', 'paid'::pricing_model, 'Subscription with a 5-day free trial; check current pricing', array['nba','mlb']::text[], 'Positive EV and arbitrage', array['Free trial','Web app','Discord community','Projections','Positive EV finder','Odds comparison','Line movement tracking','Alerts and notifications','Injury and lineup news']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "The site publishes its own results (ROI, win rate, closing line value). These are self-reported; do not repeat them as fact. It compares US sportsbooks, prediction markets and an offshore book (Bovada), none licensed in Australia. No social links on the homepage; ask for them. US flag is a best guess (Sharpr LLC).", "country": "US", "categories": ["Positive EV and arbitrage", "Player prop research", "Models and projections", "Alerts and line movement"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Sharpr')) on conflict (slug) do nothing;
