insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'rategame', 'RateGame', array['tool','community']::listing_type[], 'Rate the sports games you watch and see what other fans thought.', 'A free app where fans rate the games they watch and see weekly lists of the best games and players, ranked by the community. Built for fans, not gamblers.', 'https://x.com/RateGame_Sports', 'free'::pricing_model, null, array['nba','nfl','nhl']::text[], 'Community and social betting', array['Free plan','iOS app']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Not a betting product, so decide whether it belongs on Grinners. Add the App Store link from their X profile, confirm the sports covered and whether there is an Android app. The category is the closest fit; change or remove it. US flag is a best guess.", "country": "US", "categories": ["Community and social betting"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('RateGame')) on conflict (slug) do nothing;
