insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'playerprops-ai', 'PlayerProps.ai', array['tool']::listing_type[], 'AI projections that tell you whether a prop is a good bet before you place it.', 'PlayerProps.ai projects player props, moneylines, spreads and totals, then scores each bet against a checklist of edge, model accuracy, recent form and matchup. It shows line movement and betting splits, and lets you ask the AI or the community about any pick.', 'https://playerprops.ai/welcome', 'freemium'::pricing_model, 'Free to start without a card; USD $20 week pass, then $59 a month', array['nfl','nba','mlb','nhl']::text[], 'Player prop research', array['Free plan','Web app','Projections','Player prop hit rates','Line movement tracking']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Marketing leans on ''start winning'' and a ''100K+ winning community''; do not repeat either. Model accuracy figures are their own. Prices were read from the site on 27 November 2026; confirm. US flag is a best guess.", "country": "US", "categories": ["Player prop research", "Models and projections"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('PlayerProps.ai')) on conflict (slug) do nothing;
