insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select '4th-and-data', '4th & Data', array['creator']::listing_type[], 'Fantasy football backed by the maths: rankings, streamers and matchup charts.', 'A fantasy football account covering redraft, dynasty and rookies, with every call backtested. Posts weekly rankings by position, defence-versus-position charts and streamer picks for players rostered in under half of leagues.', 'https://x.com/4thandDataFF', 'free'::pricing_model, null, array['nfl']::text[], null, array['Fantasy rankings','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Small account (about 1,000 followers), based in Miami per the profile. Fantasy only, no betting promotion seen. Low risk.", "country": "US"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('4th & Data')) on conflict (slug) do nothing;
